 public static class Program {
  [STAThread] public static int Main(string[] args){
   if(args.Contains("--self-test"))return SelfTest();
   if(args.Contains("--settings-test"))return SettingsTest();
   if(args.Contains("--resource-test")){using(var sampler=new ResourceSampler()){sampler.Sample("");System.Threading.Thread.Sleep(2200);var value=sampler.Sample("");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"resource-test.json"),J.Json(J.Obj("cpu",value.Cpu,"gpu",value.Gpu,"memory",value.Memory,"download",value.Download,"upload",value.Upload,"diskRead",value.DiskRead,"diskWrite",value.DiskWrite,"networkName",value.NetworkName,"cpuProcesses",value.CpuProcesses.Select(p=>J.Obj("name",p.Name,"percent",p.Percent)).ToArray(),"gpuProcesses",value.GpuProcesses.Select(p=>J.Obj("name",p.Name,"percent",p.Percent)).ToArray(),"memoryProcesses",value.MemoryProcesses.Select(p=>J.Obj("name",p.Name,"percent",p.Percent)).ToArray())));return value.Cpu.HasValue&&value.Memory.HasValue?0:1;}}
   if(args.Contains("--engine-test")){var engine=new MonitorEngine(Settings.Load());engine.Refresh().GetAwaiter().GetResult();engine.Refresh().GetAwaiter().GetResult();engine.RefreshUsage().GetAwaiter().GetResult();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"engine-result.json"),J.Json(J.Obj("connected",engine.Connected,"cards",Card.Sort(engine.Cards.Values,engine.Settings).Select(c=>J.Obj("title",c.Title,"host",c.Host,"status",c.Status,"stale",c.Stale,"hasProgress",c.Message.Length>0,"messageUnavailable",c.MessageUnavailable,"questionPending",c.QuestionPending)).ToArray(),"weeklyRemaining",engine.Usage.WeeklyRemaining)));return engine.Connected?0:1;}
   if(args.Contains("--probe")){try{Probe(args).GetAwaiter().GetResult();return 0;}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"probe-result.json"),J.Json(J.Obj("ok",false,"error",e.Message)));return 1;}}
   var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};app.DispatcherUnhandledException+=(o,e)=>{e.Handled=true;try{Directory.CreateDirectory(Settings.DataDir);File.AppendAllText(Path.Combine(Settings.DataDir,"error.log"),DateTime.Now+" "+e.Exception.GetType().Name+": "+e.Exception.Message+Environment.NewLine);}catch{}};
   var w=new StripWindow(args.Contains("--demo")||args.Contains("--tray-test"));app.MainWindow=w;TrayHost tray=null;if(((!args.Contains("--demo")&&!args.Contains("--snapshot"))||args.Contains("--tray-test"))&&!args.Contains("--fullscreen-test")){tray=new TrayHost(w);w.ApplyTheme();}app.SessionEnding+=(sender,e)=>{w.Exiting=true;}; int theme=Array.IndexOf(args,"--theme");if(theme>=0&&theme+1<args.Length)w.SetTheme(args[theme+1]);int width=Array.IndexOf(args,"--width");if(width>=0&&width+1<args.Length)w.Width=double.Parse(args[width+1]);
   int height=Array.IndexOf(args,"--height");if(height>=0&&height+1<args.Length)w.Height=double.Parse(args[height+1]);int uiScale=Array.IndexOf(args,"--ui-scale");if(uiScale>=0&&uiScale+1<args.Length)w.SetUiScale(double.Parse(args[uiScale+1]));if(args.Contains("--fullscreen"))w.Loaded+=delegate{w.ToggleFullscreen();};if(args.Contains("--sleep-demo"))w.Loaded+=delegate{w.ShowSleepDemo();};int snap=Array.IndexOf(args,"--snapshot");if(snap>=0&&snap+1<args.Length){w.Loaded+=delegate{var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(SnapshotDelay(args))};t.Tick+=delegate{t.Stop();w.Snapshot(args[snap+1]);int preview=Array.IndexOf(args,"--preview-snapshot");if(preview>=0&&preview+1<args.Length)w.SnapshotPreview(args[preview+1]);int q=Array.IndexOf(args,"--usage-snapshot");if(q>=0&&q+1<args.Length)w.SnapshotUsage(args[q+1]);int setting=Array.IndexOf(args,"--settings-snapshot");if(setting>=0&&setting+1<args.Length)w.SnapshotSettings(args[setting+1]);int bottom=Array.IndexOf(args,"--settings-bottom-snapshot");if(bottom>=0&&bottom+1<args.Length)w.SnapshotSettingsBottom(args[bottom+1]);w.Close();};t.Start();};}
   if(args.Contains("--tray-test")){w.Loaded+=delegate{var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(300)};timer.Tick+=delegate{timer.Stop();try{if(w.ShowInTaskbar||!tray.Visible)throw new Exception("tray startup");w.Close();if(w.IsVisible||!tray.Visible||w.Exiting)throw new Exception("close should hide");tray.Show();if(!w.IsVisible||w.ShowInTaskbar)throw new Exception("restore");w.ShowSettings();foreach(Window child in w.OwnedWindows)if(child.ShowInTaskbar)throw new Exception("popup taskbar");tray.Toggle();if(w.IsVisible||w.OwnedWindows.Count!=0)throw new Exception("hide children");tray.Show();tray.Exit();if(tray.Visible)throw new Exception("icon cleanup");File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tray-test.txt"),"PASS: no taskbar, close-to-tray, restore, popup visibility, hide children, exit cleanup");}catch(Exception e){File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tray-test.txt"),e.ToString());tray.Exit();}};timer.Start();};}
   if(args.Contains("--fullscreen-test")){w.Loaded+=delegate{var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=delegate{timer.Stop();string result;try{if(!w.DemoMode&&w.Config.ReserveWorkArea)w.ApplyDockSettings();var h=new System.Windows.Interop.WindowInteropHelper(w).Handle;WindowGeometry.RECT before,full,after;WindowGeometry.GetWindowRect(h,out before);bool docked=w.Docked;w.ToggleFullscreen();WindowGeometry.GetWindowRect(h,out full);var monitor=WindowGeometry.Bounds(h,false);if(full.left!=monitor.left||full.top!=monitor.top||full.right!=monitor.right||full.bottom!=monitor.bottom)throw new Exception("fullscreen does not cover the monitor");w.ToggleFullscreen();WindowGeometry.GetWindowRect(h,out after);if(docked&&!w.Docked)throw new Exception("dock was not restored");if(!docked&&(Math.Abs(before.left-after.left)>2||Math.Abs(before.top-after.top)>2||Math.Abs(before.right-after.right)>2||Math.Abs(before.bottom-after.bottom)>2))throw new Exception("floating bounds were not restored");result="PASS: fullscreen covers the selected monitor and restores "+(docked?"docking":"floating bounds");}catch(Exception e){result=e.ToString();}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fullscreen-test.txt"),result);w.Close();};timer.Start();};}
   if(args.Contains("--sleep-click-test")){w.Loaded+=delegate{w.ShowSleepDemo();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"sleep-click-test.txt"),w.TestSleepClick()?"PASS: clicking resource view restores tasks":"FAIL: resource view stayed visible");w.Close();};}
   try{app.Run(w);}finally{if(tray!=null)tray.Dispose();}return 0;
  }
  static async Task Probe(string[] args){var b=new Bridge();await b.Discover();var list=await b.Call("list_threads",J.Obj("limit",8));var threads=J.Arr(J.Get(list,"threads"));var target=threads.FirstOrDefault(t=>J.Str(t,"hostId").Contains("virgo"));object snapshot=null,detail=null,nav=null;
   if(target!=null){snapshot=await b.Call("wait_threads",J.Obj("targets",new[]{J.Obj("threadId",J.Str(target,"id"),"hostId",J.Str(target,"hostId"))},"timeoutMs",0));var raw=await b.Call("read_thread",J.Obj("threadId",J.Str(target,"id"),"hostId",J.Str(target,"hostId"),"turnLimit",1,"includeOutputs",false,"maxOutputCharsPerItem",200));detail=J.Obj("turnCount",J.Arr(J.Get(raw,"turns")).Length);}
   int open=Array.IndexOf(args,"--open");if(open>=0&&open+1<args.Length)nav=await b.Call("navigate_to_codex_page",J.Obj("threadId",args[open+1]));
   var usage=new Usage();usage.Update(await b.Call("get_usage_limits",J.Obj()));
   File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"probe-result.json"),J.Json(J.Obj("ok",true,"autoDiscovered",true,"context",b.ContextId,"tasks",threads.Select(t=>J.Obj("title",J.Str(t,"title"),"host",J.Str(t,"hostId"),"status",J.Str(t,"status"))).ToArray(),"remoteSnapshot",snapshot,"detail",detail,"navigation",nav,"weeklyRemaining",usage.WeeklyRemaining,"resetCardCount",usage.Count,"resetCardExpiry",usage.Credits.Select(c=>c.Expires).ToArray())));
  }
  static int SnapshotDelay(string[] args){int at=Array.IndexOf(args,"--snapshot-delay-ms"),value;return at>=0&&at+1<args.Length&&int.TryParse(args[at+1],out value)?Math.Max(100,Math.Min(30000,value)):(args.Contains("--demo")?2000:18000);}
  static void TestRateReadout(){
   var trace=new RateTrace();DateTime start=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc);
   trace.SetTarget(10,20,start,true);trace.SetTarget(1000,2000,start.AddSeconds(1),true);
   for(int frame=0;frame<60;frame++)trace.Step(1.0/30);
   if(trace.DisplayFirst!=10||trace.DisplaySecond!=20)throw new Exception("rate digits changed during hold");
   trace.SetTarget(10,20,start.AddSeconds(2),true);trace.SetTarget(20,40,start.AddSeconds(3),true);
   if(trace.DisplayFirst!=260||trace.DisplaySecond!=520)throw new Exception("rate average publish");
   trace.SetTarget(20,40,start.AddSeconds(4),true);trace.SetTarget(20,40,start.AddSeconds(5),true);trace.SetTarget(30,60,start.AddSeconds(6),true);
   if(trace.DisplayFirst!=20||trace.DisplaySecond!=40)throw new Exception("old rate spike did not expire");
   trace.SetTarget(null,null,start.AddSeconds(12),true);if(trace.DisplayFirst.HasValue||trace.DisplaySecond.HasValue)throw new Exception("missing rate displayed as zero");
  }
  static void TestAsyncReply(){
   string reply="<send_user_message_question_reply>\n[{\"questionItemId\":\"[\\\"request_user_input_async\\\",\\\"call_x\\\",0]\",\"question\":\"Q?\",\"answer\":\"A\"}]\n</send_user_message_question_reply>";
   var user=J.Obj("type","response_item","payload",J.Obj("type","message","role","user","content",new object[]{J.Obj("text",reply)}));
   if(LocalMessages.ReplyQuestionText(user)!="Q?")throw new Exception("local async reply parse");
   var turn=J.Obj("turnStartedAtMs",1234,"turnId","t","status","inProgress","items",new object[]{J.Obj("type","userMessage","input",new object[]{J.Obj("text",reply)})});
   var state=J.Obj("threadRuntimeStatus",J.Obj("type","active"),"turns",new object[]{turn},"requests",new object[]{J.Obj("params",J.Obj("questions",new object[]{J.Obj("question","Q?")}))});
   if(StreamState.Project(state,"local","thread").QuestionPending)throw new Exception("answered request remained pending");
  }
  static int SelfTest(){try{var s=new Settings{Count=2};Card a=new Card{Id="a",Host="local",Interaction=10},b=new Card{Id="b",Host="remote-ssh-discovered:virgo",Interaction=20},c=new Card{Id="c",Host="local",Interaction=30};if(Card.Sort(new[]{a,b,c},s)[0]!=c)throw new Exception("recency");s.Clicks[a.Key]=40;if(Card.Sort(new[]{a,b,c},s)[0]!=a)throw new Exception("click recency");s.Host=b.Host;if(Card.Sort(new[]{a,b,c},s).Length!=1)throw new Exception("host filter");var u=new Usage();u.Update(J.Parse("{\"rateLimits\":{\"primary\":{\"usedPercent\":29,\"windowDurationMins\":10080,\"resetsAt\":123}},\"rateLimitResetCredits\":{\"availableCount\":1,\"credits\":[{\"status\":\"available\",\"expiresAt\":456}]}}"));if(u.WeeklyRemaining!=71||u.Credits[0].Expires!=456)throw new Exception("usage");u.Update(J.Parse("{}"));if(u.WeeklyRemaining!=null||u.Count!=null)throw new Exception("missing usage");a.Snapshot(J.Parse("{\"thread\":{\"status\":{\"type\":\"active\",\"activeFlags\":[\"waitingOnApproval\"]}},\"latestTurn\":{\"id\":\"t\",\"status\":\"inProgress\",\"startedAt\":55}}"));if(a.Status!="approval"||a.Interaction!=55)throw new Exception("approval state");var motion=new RingMotion{Target=80};for(int frame=0;frame<45;frame++){double priorVelocity=motion.Velocity;motion.Step(1.0/30);if(Math.Abs(motion.Velocity)>160.001||Math.Abs(motion.Velocity-priorVelocity)>20.001)throw new Exception("ring speed or acceleration cap");}if(Math.Abs(motion.Value-80)>3||Math.Abs(motion.Velocity)>160)throw new Exception("ring motion convergence");motion.Target=20;for(int frame=0;frame<90;frame++)motion.Step(1.0/30);if(Math.Abs(motion.Value-20)>.2)throw new Exception("ring motion retargeting");var ringParts=new RingMetricMotion();ringParts.SetTarget(60,new[]{new ResourcePart("app",25)});for(int frame=0;frame<60;frame++)ringParts.Step(1.0/30);ringParts.SetTarget(15,new ResourcePart[0]);for(int frame=0;frame<90;frame++)ringParts.Step(1.0/30);if(ringParts.Parts.Count!=0||Math.Abs(ringParts.Total.Value-15)>.2)throw new Exception("ring segment retirement");var rate=new RateMotion{Target=8*1048576};for(int frame=0;frame<60;frame++)rate.Step(1.0/30);if(Math.Abs(rate.Value-rate.Target)>rate.Target*.03)throw new Exception("rate motion convergence");rate.Target=0;for(int frame=0;frame<90;frame++)rate.Step(1.0/30);if(rate.Value>rate.Target+1024)throw new Exception("rate motion decay");var trace=new RateTrace();trace.SetTarget(4*1048576,1048576,DateTime.UtcNow,true);if(trace.History.Count!=1||!trace.First.Available||!trace.Second.Available)throw new Exception("rate trace sample");TestRateReadout();TestAsyncReply();var quiet=new Card{Status="completed"};if(!SleepPolicy.Quiet(true,new[]{quiet})||SleepPolicy.Quiet(false,new[]{quiet}))throw new Exception("quiet connection");quiet.Unread=true;if(SleepPolicy.Quiet(true,new[]{quiet}))throw new Exception("unread must wake");quiet.Unread=false;quiet.Status="active";if(SleepPolicy.Quiet(true,new[]{quiet}))throw new Exception("active must wake");quiet.Status="approval";if(SleepPolicy.Quiet(true,new[]{quiet}))throw new Exception("approval must wake");if(!SleepPolicy.Due(DateTime.UtcNow.AddMinutes(-6),DateTime.UtcNow,5)||SleepPolicy.Due(DateTime.UtcNow.AddMinutes(-4),DateTime.UtcNow,5))throw new Exception("idle delay");var completedCard=new Card{Status="completed"};if(!MonitorEngine.NewCompletion(new Card{Status="active"},completedCard))throw new Exception("completion transition");completedCard.Stale=true;if(MonitorEngine.NewCompletion(new Card{Status="active"},completedCard))throw new Exception("stale completion");var fresh=new Card{Id="sync",Host="local",Status="active",Stale=false};var staleLive=new Card{Id="sync",Host="local",Status="completed",Stale=true};if(MonitorEngine.PreferFresh(fresh,staleLive)!=fresh)throw new Exception("stale stream overrode a fresh poll");staleLive.Stale=false;if(MonitorEngine.PreferFresh(fresh,staleLive)!=staleLive)throw new Exception("fresh stream was ignored");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test.txt"),"PASS: card ordering, usage, attention, quiet state, idle delay, fresh poll precedence, smooth ring motion, async reply clearing, rate curves, stable rate readout.");return 0;}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test.txt"),e.ToString());return 1;}}
  static int SettingsTest(){string original=Settings.DataDir;try{Settings.DataDir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings-test-data");var value=new Settings{SleepAuto=true,SleepRingCharts=false,SleepSmoothRings=false,SleepIdleMinutes=10,SleepWidgets=new List<string>{"gpu","network"},SleepSpeedUnit="mbps",SleepAccent="green",SleepDim=.6,SleepWallpaperPath="C:\\sample-wallpaper.png"};value.PendingCompletions["local/example"]="turn-1";value.RememberScale("DISPLAY1",1.25);value.RememberScale("DISPLAY2",1.75);value.Save();var loaded=Settings.Load();if(loaded.PendingCompletions["local/example"]!="turn-1")throw new Exception("pending completion roundtrip");if(loaded.ScaleForMonitor("DISPLAY1")!=1.25||loaded.ScaleForMonitor("DISPLAY2")!=1.75||loaded.ScaleForMonitor("NEW")!=1.5)throw new Exception("monitor scale roundtrip");if(loaded.SleepRingCharts||loaded.SleepSmoothRings||loaded.SleepIdleMinutes!=10||loaded.SleepWidgets.Count!=2||loaded.SleepWidgets[0]!="gpu"||loaded.SleepWidgets[1]!="network"||loaded.SleepSpeedUnit!="mbps"||loaded.SleepAccent!="green"||Math.Abs(loaded.SleepDim-.6)>.001||loaded.SleepWallpaperPath!=value.SleepWallpaperPath)throw new Exception("sleep settings roundtrip");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings-test.txt"),"PASS: sleep, monitor scale, and completion acknowledgement settings survive save and load");return 0;}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings-test.txt"),e.ToString());return 1;}finally{Settings.DataDir=original;}}
 }
